text_dim = Color3.fromHex("A3A3A3"),
accent = Color3.fromHex("7CFA3A"),
accent_2 = Color3.fromHex("94FF59"),
accent_fill = Color3.fromHex("5FCB23"),
accent_soft = Color3.fromHex("273C20"),
accent_dim = Color3.fromHex("59AD2F"),
knockout = Color3.fromHex("08140A"),
scroll = Color3.fromHex("445249"),
white = Color3.fromHex("FFFFFF"),
danger = Color3.fromHex("FF6B6B"),
success = Color3.fromHex("7CFA3A"),
warning = Color3.fromHex("FFC53D"),
info = Color3.fromHex("BABABA"),
}
Theme.PaletteNames = { "uranium green", "midnight blue", "violet", "rose", "neutral graphite" }
Theme.Palettes = { ["uranium green"] = table.clone(Theme.Colors) }
local function palette(values)
local colors = table.clone(Theme.Colors)
local keys = { "chrome", "bg", "card", "pop", "control", "control_hi",
"toggle_off", "knob", "border", "border_soft", "text", "text_muted",
"text_dim", "accent", "knockout", "scroll" }
for i, key in keys do colors[key] = Color3.fromHex(values[i]) end
colors.info = colors.text_muted
colors.accent_2 = colors.accent:Lerp(colors.white, 0.15)
colors.accent_fill = colors.accent:Lerp(colors.chrome, 0.18)
colors.accent_soft = colors.card:Lerp(colors.accent, 0.13)
colors.accent_dim = colors.accent:Lerp(colors.chrome, 0.35)
return colors
end
Theme.Palettes["midnight blue"] = palette({
"0B101B", "101827", "182337", "1D2A40", "233149", "2D3E59",
"354964", "829AB9", "3C506F", "293A53", "EDF3FC", "ACBCD3",
"9BAAC1", "79B8FF", "091421", "506A8D",
})
Theme.Palettes.violet = palette({
