"5B4050", "BB96A8", "604453", "432E39", "FCEFF5", "D1B1C0",
"BEA3B2", "FF9DBE", "250F18", "80566B",
})
Theme.Palettes["neutral graphite"] = palette({
"0D0F12", "14171B", "1D2127", "242931", "2B313A", "363D48",
"414955", "9BA5B4", "46505E", "303742", "F1F3F6", "B8C0CC",
"A0A9B6", "C2CBD8", "10151C", "5D697A",
})
Theme.Colors = table.clone(Theme.Palettes["uranium green"])
function Theme.resolvePalette(name)
local key = if type(name) == "string" then name:lower() else "uranium green"
