local paintPlayPause
local paintShuffle
local paintLoop
local paintFavorite
local startTicking
local stopTicking
local seekTo
local attachTrackAudio
local loadTrackData
local gotoIndex
local pickIndex
local handleEnded
local doPlay
local doPause
local applyVolume
local applyShuffle
local applyLoop
local doNext
local doPrevious
