Size = UDim2.new(1, 0, 0, 0),
AutomaticSize = Enum.AutomaticSize.Y,
}, {
Create.listLayout({}),
})
local headPad = Create.padding(9, 0)
local head = Create("TextButton", {
Name = "Head",
AutoButtonColor = false,
Text = "",
BackgroundTransparency = 1,
Size = UDim2.new(1, 0, 0, 0),
AutomaticSize = Enum.AutomaticSize.Y,
LayoutOrder = 1,
Parent = section,
}, {
headPad,
})
local function fitHead()
local pad = ctx:IsTouch() and 12 or 9
headPad.PaddingTop = UDim.new(0, pad)
headPad.PaddingBottom = UDim.new(0, pad)
end
fitHead()
local unsubscribeTouch = ctx:OnTouch(fitHead)
section.Destroying:Connect(unsubscribeTouch)
Create("TextLabel", {
Name = "Title",
BackgroundTransparency = 1,
AutomaticSize = Enum.AutomaticSize.Y,
Size = UDim2.new(1, -18, 0, 0),
Text = opts.Title or "Section",
TextColor3 = ctx:Color(function() return colors.text_muted end),
TextSize = 12,
FontFace = Theme.Font.Medium,
TextXAlignment = Enum.TextXAlignment.Left,
Parent = head,
})
local chevron = Icons.new("chev", 14, ctx:Color(function() return colors.text_dim end))
chevron.AnchorPoint = Vector2.new(1, 0.5)
chevron.Position = UDim2.new(1, 0, 0.5, 0)
chevron.Rotation = collapsed and 180 or 0;
(chevron ).Parent = head
local bodyWrap = Create("Frame", {
Name = "BodyWrap",
BackgroundTransparency = 1,
Size = UDim2.new(1, 0, 0, 0),
AutomaticSize = Enum.AutomaticSize.Y,
})
local body = Create("Frame", {
Name = "Body",
BackgroundTransparency = 1,
Position = UDim2.fromOffset(14, 0),
Size = UDim2.new(1, -14, 0, 0),
AutomaticSize = Enum.AutomaticSize.Y,
Parent = bodyWrap,
}, {
Create.padding(1, 0, 8, 0),
Create.listLayout({}),
})
Create("Frame", {
Name = "Rule",
Position = UDim2.fromOffset(2, 1),
Size = UDim2.new(0, 1, 1, 0),
BackgroundColor3 = ctx:Color(function() return colors.border end),
BorderSizePixel = 0,
Parent = bodyWrap,
