return ctx:GetScale()
end)
holder.LayoutOrder = 2
holder.Parent = section
local function draw(folded, animate)
if animate then Tween.play(chevron, Tween.Spin, { Rotation = folded and 180 or 0 })
else chevron.Rotation = folded and 180 or 0 end
setCollapsed(folded, animate)
end
