expand = function(expand) draw(if expand then false else collapsed, false) end,
reveal = function() collapsed = false; draw(false, false) end,
}
head.Activated:Connect(function()
collapsed = not collapsed
draw(collapsed, true)
end)
return section, body, search
end
end
