end
end
g:ButtonRow({
{ Label = "save config", Desc = "Write current settings to the named config, replacing its saved values.", Tone = "warn", Callback = save },
{ Label = "load config", Desc = "Apply the selected config to the current settings.", Callback = load },
})
g:ButtonRow({
{ Label = "delete config", Tone = "danger", Desc = "Permanently delete the selected saved config file.", Callback = remove },
{ Label = "refresh configs", Callback = refresh },
})
autoSwitch = g:Toggle({
Name = "Auto Load",
Desc = "Apply the selected config on launch.",
Default = window:GetAutoload() ~= nil,
Hud = false,
Callback = syncAutoload,
})
controls.Name = nameBox
controls.List = list
controls.AutoLoad = autoSwitch
controls.OnSelect = function(fn)
