if inline then
g:Divider()
end
controls.Unload = g:Button({
Tone = "danger",
Desc = "Close this menu and disconnect its listeners. Run the loader again to reopen it.",
Label = o.Label or ("unload " .. Theme.Brand.name),
Callback = function()
task.defer(function()
window:Destroy()
end)
end,
})
return controls
end
function Settings.build(window, tab, opts)
local o= opts or {}
local sections= o.Sections or {}
if type(sections) ~= "table" then
