Log.fail("CreateSubpage", 'requires { Id = "stable-id", Name = "Label" }')
end
Log.field("CreateSubpage", "Name", options.Name, "string")
local id = options.Id
if byId[id] then return byId[id].content end
local name = options.Name or id
local content = TabContent(ctx, scope .. "::page[" .. #id .. ":" .. id .. "]", label)
content.page.Name = "Subpage_" .. id
content.page.LayoutOrder = #pages + 1
content.page.Parent = root
content:_setStacked(stacked)
local columns = content.page:FindFirstChild("Columns")
local slot = Create("Frame", {
Name = "MotionSlot", BackgroundTransparency = 1,
Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y,
LayoutOrder = 2, Parent = content.page,
})
columns.Parent = slot
local motion = PageMotion.new(columns)
Create.listLayout({ Parent = content.page, Padding = UDim.new(0, 8) })
local heading = Create("TextButton", {
Name = "SearchPage", Text = name .. " · Show page →", TextSize = 13,
FontFace = Theme.Font.Medium, TextXAlignment = Enum.TextXAlignment.Left,
TextColor3 = ctx:Color(function() return colors.text end),
BackgroundTransparency = 1, AutoButtonColor = false,
Size = UDim2.new(1, 0, 0, 44), LayoutOrder = 1, Visible = false,
Parent = content.page,
})
local button = Create("TextButton", {
Name = "Subpage_" .. id, Text = name, TextSize = 13,
FontFace = Theme.Font.Medium, AutoButtonColor = false,
Size = UDim2.fromOffset(84, 44), AutomaticSize = Enum.AutomaticSize.X,
LayoutOrder = #pages + 1, Parent = nav,
}, { Create.corner(Theme.Metrics.controlRadius), Create.padding(0, 16) })
button.NextSelectionLeft = button
button.NextSelectionRight = button
local entry = { id = id, content = content, button = button, hovered = false,
heading = heading, scroll = Vector2.zero, matches = 0, first = nil, motion = motion, order = #pages + 1 }
button.MouseEnter:Connect(function() entry.hovered = true; paintButton(entry, true) end)
button.MouseLeave:Connect(function() entry.hovered = false; paintButton(entry, true) end)
table.insert(pages, entry)
byId[id] = entry
selected = selected or id
function content:Select() return manager:Select(id) end
function content:IsActive()return active and selected == id end
function content:GetId()return id end
button.Activated:Connect(function() ctx:User(function() manager:Select(id) end) end)
heading.Activated:Connect(function()
local first = entry.first
for _, candidate in content.groups do
if candidate._search.group.Visible then
local a = candidate._search.group.AbsolutePosition
local b = first and first._search.group.AbsolutePosition
if not b or a.Y < b.Y or (a.Y == b.Y and a.X < b.X) then first = candidate end
end
end
if tab._clearSearch then tab._clearSearch() else manager:Filter("") end
manager:Select(id)
if first then
content:Reveal(first)
task.defer(function()
if selected ~= id or not active or not ctx.Scroller then return end
local y = ctx:ToLayout(first._search.group.AbsolutePosition.Y - ctx.Scroller.AbsolutePosition.Y)
manager:RestoreScroll(Vector2.new(0, math.max(0, ctx.Scroller.CanvasPosition.Y + y)))
end)
end
end)
paint()
if tab._onPagesChanged then tab._onPagesChanged() end
return content
end
local keyConnection = Services.UserInputService.InputBegan:Connect(function(input)
if not active or Services.UserInputService:GetFocusedTextBox() then return end
local focused = Services.GuiService.SelectedObject
local index = nil
for i, entry in pages do if focused == entry.button then index = i; break end end
if not index then return end
local key = input.KeyCode
if key == Enum.KeyCode.Left or key == Enum.KeyCode.DPadLeft then index = (index - 2) % #pages + 1
elseif key == Enum.KeyCode.Right or key == Enum.KeyCode.DPadRight then index = index % #pages + 1
elseif key == Enum.KeyCode.Home then index = 1
elseif key == Enum.KeyCode.End then index = #pages
else return end
ctx:User(function() manager:Select(pages[index].id) end)
Services.GuiService.SelectedObject = pages[index].button
end)
nav.Destroying:Connect(function()
keyConnection:Disconnect()
if ctx._navigation == navigation then ctx._navigation = nil end
end)
function manager:ResetFilter()
for _, entry in pages do entry.content:ResetFilter() end
end
function manager:Filter(value)
local q = string.lower(value or "")
if q == query then return end
if query == "" and q ~= "" then
saveScroll()
beforeSearch = { id = selected, scroll = ctx.Scroller and ctx.Scroller.CanvasPosition or Vector2.zero }
ctx:LeavePage(root)
end
query = q
local total = 0
for _, entry in pages do
entry.matches, entry.first = entry.content:Filter(q)
total += entry.matches
end
empty.Visible = q ~= "" and total == 0
if q == "" and beforeSearch then selected = beforeSearch.id end
paint()
if q == "" then
self:RestoreScroll(beforeSearch and beforeSearch.scroll)
beforeSearch = nil
elseif active then self:RestoreScroll(Vector2.zero) end
end
if active then ctx._navigation = navigation end
return manager
end
end
