local function select(index, animate)
local direction = if animate and index ~= activeIndex then (if index > activeIndex then 1 else -1) else nil
local previous = tabs[activeIndex]
if previous then
ctx:LeavePage(previous.page)
if previous._pages then previous._pages:SaveScroll(); previous:Filter("") end
end
activeIndex = index
ctx:ClosePopover()
for i, tab in tabs do
tab:_setActive(i == index, direction)
end
content.CanvasPosition = Vector2.new(0, 0)
applySearch(currentQuery())
if tabs[index] and tabs[index]._pages and currentQuery() == "" then tabs[index]._pages:RestoreScroll() end
if tabs[index] and tabs[index]._onPagesChanged then tabs[index]._onPagesChanged() end
end
local function chooseTab(index)
select(index, true)
ctx:WindowStateChanged()
end
