end
end
end
end
for _, tab in deps.tabs() do
if tab._pages then
local id = type(value.Pages) == "table" and value.Pages[tab._scope] or nil
if not (type(id) == "string" and tab._pages:Select(id, true)) then
tab._pages:Select(tab._pages:FirstId(), true)
end
end
end
